style.css:
/* ? Fond global */
body {
  background-color: #121212 !important;
}

/* ? Barre du haut (le blanc → gris foncé) */
header,
div[data-test-id="header"] {
  background-color: #111 !important;
}

/* ? Barre de recherche */
input {
  background-color: #1e1e1e !important;
  color: inherit !important; /* remet couleur normale */
}

/* ? Sidebar gauche */
div[role="navigation"],
nav {
  background-color: #111 !important;
}

/* ? Contenu */
main,
section {
  background-color: #121212 !important;
}

/* ?️ Cards */
div[data-test-id="pin"] {
  background-color: #1a1a1a !important;
  border-radius: 15px !important;
}

/* ?️ Images */
img {
  border-radius: 15px !important;
}

/* ? Boutons */
button {
  background-color: #1e1e1e !important;
  color: inherit !important; /* texte normal */
}

/* ? TEXTE → remettre normal */
span,
p,
h1, h2, h3, h4, h5, h6 {
  color: inherit !important;
}

/* ? Liens */
a {
  color: inherit !important;
}

/* Hover */
button:hover {
  background-color: #333 !important;
}
